function countBookendPairs(words: string[]): number {
  const seen = new Map<string, number>();
  let count = 0;
  for (const w of words) {
    for (let len = 1; len <= w.length; len++) {
      const piece = w.slice(0, len);
      if (w.endsWith(piece)) count += seen.get(piece) ?? 0;
    }
    seen.set(w, (seen.get(w) ?? 0) + 1);
  }
  return count;
}

