    def countBookendPairs(self, words: List[str]) -> int:
        seen = Counter()
        count = 0
        for w in words:
            for length in range(1, len(w) + 1):
                piece = w[:length]
                if w.endswith(piece):
                    count += seen[piece]
            seen[w] += 1
        return count

